import { queryExecutionClient } from '@dynatrace-sdk/client-query';

export default async function () {
  const query = `
fetch dt.system.events, timeframe:"${$dt_timeframe_from}/${$dt_timeframe_to}"
| filter event.kind == "AUDIT_EVENT"
| limit 1
  `.trim();

  const response = await queryExecutionClient.queryExecute({ body: { query } });
  const record = response?.result?.records?.[0] ?? {};

  const keys = Object.keys(record).sort((a, b) => a.localeCompare(b));

  // Return keys as a simple table so you can see them in a dashboard tile
  const records = keys.map(k => ({ field: k, valuePreview: record[k] }));

  return {
    records,
    types: [
      {
        mappings: {
          field: { type: 'string' },
          valuePreview: { type: 'string' },
        },
        indexRange: [0, records.length],
      },
    ],
  };
}

