import { queryExecutionClient } from '@dynatrace-sdk/client-query';

export default async function () {
  // Escape values so quotes/backslashes don't break the query
  const esc = (s: any) => String(s).replace(/\\/g, '\\\\').replace(/"/g, '\\"');

  const toArrayMax5 = (v: any) => {
    if (!v) return [];
    const arr = Array.isArray(v) ? v : [v];
    return arr.slice(0, 5);
  };

  // Build OR group: (field == "a" or field == "b")
  const orGroup = (field: string, values: any[]) => {
    const vals = values.filter(x => x !== null && x !== undefined && String(x).length > 0);
    if (vals.length === 0) return '';
    return `(${vals.map(v => `${field} == "${esc(v)}"`).join(' or ')})`;
  };

  const filters: string[] = [];

  // User
  const users = toArrayMax5($User);
  if (Array.isArray($User) && $User.length > 5) console.log('More than 5 users selected; only first 5 will be used.');
  if (!Array.isArray($User) && users.length > 0) { /* ok */ }
  if (users.length > 0) filters.push(orGroup('user', users));

  // EventType
  const eventTypes = toArrayMax5($EventType);
  if (Array.isArray($EventType) && $EventType.length > 5) console.log('More than 5 eventTypes selected; only first 5 will be used.');
  if (eventTypes.length > 0) filters.push(orGroup('eventType', eventTypes));

  // Category
  const categories = toArrayMax5($Category);
  if (Array.isArray($Category) && $Category.length > 5) console.log('More than 5 categories selected; only first 5 will be used.');
  if (categories.length > 0) filters.push(orGroup('category', categories));

  // EntityId
  const entityIds = toArrayMax5($EntityId);
  if (Array.isArray($EntityId) && $EntityId.length > 5) console.log('More than 5 entityIds selected; only first 5 will be used.');
  if (entityIds.length > 0) filters.push(orGroup('entityId', entityIds));

  const extraFilterLine = filters.length > 0 ? `| filter ${filters.join(' and ')}` : '';

  const query = `
fetch dt.system.events, timeframe:"${$dt_timeframe_from}/${$dt_timeframe_to}"
| filter event.kind == "AUDIT_EVENT"
${extraFilterLine}
| summarize Total = count()
  `.trim();

  const response = await queryExecutionClient.queryExecute({
    body: { query },
  });

  const records = response?.result?.records ?? [];
  const total = records[0]?.Total ?? 0;

  const types = [
    {
      mappings: { Total: { type: 'integer' } },
      indexRange: [0, 1],
    },
  ];

  const dataFrame = {
    types,
    records: [{ Total: total }],
  };

  return dataFrame;
}

